<script setup lang="ts">
import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, Link2, Undo2, Redo2, Eraser } from 'lucide-vue-next'
import type { Palette } from '@qinbian/shared'
const props=defineProps<{editor:any;palette?:Palette;mappings?:Record<string,string>}>(),ctx=useQinbian(),linkOpen=ref(false),linkValue=ref(''),colorOpen=ref(false),tick=ref(0)
const changed=()=>tick.value++
watch(()=>props.editor,(e,old)=>{old?.off('transaction',changed);e?.on('transaction',changed)})
onBeforeUnmount(()=>props.editor?.off('transaction',changed))
const currentColor=computed(()=>{tick.value;return props.editor?.getAttributes('textStyle').color||'#183a49'})
function command(name:string,...args:any[]){if(!props.editor)return;const chain=props.editor.chain().focus();chain[name](...args).run()}
function chooseColor(choice:{token?:string;value:string}){command('setMark','textStyle',{color:choice.value,colorToken:choice.token||null,customColor:!choice.token});colorOpen.value=false}
function clearFormat(){if(!props.editor)return;props.editor.chain().focus().unsetBold().unsetItalic().unsetUnderline().unsetStrike().unsetCode().unsetLink().setMark('textStyle',{color:null,fontSize:null,fontFamily:null,colorToken:null,customColor:false}).run()}
function preserveSelection(event:MouseEvent){if((event.target as Element).closest('button'))event.preventDefault()}
function link(){if(linkValue.value&&!/^(https?:\/\/|mailto:|tel:|#)/i.test(linkValue.value)){ctx.notify('请使用完整的http、https、邮箱或电话链接',true);return}if(linkValue.value)command('setLink',{href:linkValue.value});else command('unsetLink');linkOpen.value=false}
</script>
<template><div class="rich-toolbar" aria-label="文字编辑工具" @mousedown="preserveSelection"><span v-if="!editor" class="toolbar-hint">点一段文字，便可落笔。</span><template v-else><button class="icon-button" :class="{active:editor.isActive('bold')}" aria-label="加粗" title="加粗" @click="command('toggleBold')"><Bold :size="16"/></button><button class="icon-button" :class="{active:editor.isActive('italic')}" aria-label="斜体" @click="command('toggleItalic')"><Italic :size="16"/></button><button class="icon-button" :class="{active:editor.isActive('underline')}" aria-label="下划线" @click="command('toggleUnderline')"><Underline :size="16"/></button><span class="tool-divider"/><select aria-label="字体" @change="command('setMark','textStyle',{fontFamily:($event.target as HTMLSelectElement).value})"><option value="">字体</option><option value="Songti SC, STSong, SimSun, serif">宋体</option><option value="PingFang SC, Microsoft YaHei, sans-serif">黑体</option><option value="STKaiti, KaiTi, serif">楷体</option></select><select aria-label="字号" @change="command('setMark','textStyle',{fontSize:($event.target as HTMLSelectElement).value})"><option value="">字号</option><option v-for="n in [11,12,13,14,15,16,18,20,22,24]" :key="n" :value="n+'px'">{{n}}</option></select><button class="icon-button text-color-button" aria-label="文字颜色" title="文字颜色与主题映射" @click="colorOpen=true"><span :style="{borderBottomColor:currentColor}">文</span></button><span class="tool-divider"/><button class="icon-button" aria-label="左对齐" @click="command('setTextAlign','left')"><AlignLeft :size="16"/></button><button class="icon-button" aria-label="居中" @click="command('setTextAlign','center')"><AlignCenter :size="16"/></button><button class="icon-button" aria-label="右对齐" @click="command('setTextAlign','right')"><AlignRight :size="16"/></button><button class="icon-button" aria-label="设置链接" @click="linkValue=editor.getAttributes('link').href||'';linkOpen=true"><Link2 :size="16"/></button><button class="icon-button" aria-label="清除文字格式" @click="clearFormat"><Eraser :size="16"/></button><button class="icon-button" aria-label="撤销文字修改" @click="command('undo')"><Undo2 :size="15"/></button><button class="icon-button" aria-label="重做文字修改" @click="command('redo')"><Redo2 :size="15"/></button></template></div><UiModal v-if="linkOpen" title="设置文字链接" @close="linkOpen=false"><form class="form-stack" @submit.prevent="link"><label>链接地址<input v-model="linkValue" placeholder="https://…"></label><p class="small muted">留空可移除现有链接。</p><div class="modal-actions"><button class="btn primary">应用链接</button></div></form></UiModal><ColorPicker v-if="colorOpen" :palette="palette" :mappings="mappings" :current="currentColor" @close="colorOpen=false" @choose="chooseColor"/></template>
